/**
 * Workflow graph generator
 *
 * Reads agents/sm.json and writes docs/agents/workflow.md with:
 *  - a human-readable rule table
 *  - a Mermaid flowchart of status -> agent -> target status edges
 *
 * Usage:
 *   dmtools run agents/js/unit-tests/run_agentDocs.json
 *   node agents/js/agentWorkflowGraph.js   (Node, not GraalJS)
 */

var fs = require('fs');
var path = require('path');

var SM_JSON = 'agents/sm.json';
var WORKFLOW_MD = 'agents/docs/agents/workflow.md';

function readJson(filePath) {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function statusNode(status) {
    var safe = status.replace(/[^a-zA-Z0-9]/g, '_');
    return 'S_' + safe + '["' + status + '"]';
}

function agentNode(configFile, idx) {
    var name = configFile.replace(/^agents\//, '').replace(/\.json$/, '');
    return 'A' + idx + '_["' + name + '"]';
}

function parseSourceStatuses(jql) {
    if (!jql) return [];
    var statuses = [];
    var m = jql.match(/status\s+in\s+\(([^)]+)\)/i);
    if (m) {
        statuses = m[1].split(',').map(function(s) {
            return s.trim().replace(/^['"]|['"]$/g, '');
        });
    } else {
        m = jql.match(/status\s*=\s*['"]([^'"]+)['"]/i);
        if (m) statuses.push(m[1]);
    }
    return statuses.filter(Boolean);
}

function parseIssueTypes(jql) {
    if (!jql) return [];
    var types = [];
    var m = jql.match(/issuetype\s+in\s+\(([^)]+)\)/i);
    if (m) {
        types = m[1].split(',').map(function(s) {
            return s.trim().replace(/^['"]|['"]$/g, '');
        });
    } else {
        m = jql.match(/issuetype\s*=\s*['"]([^'"]+)['"]/i);
        if (m) types.push(m[1]);
    }
    return types.filter(Boolean);
}

function escapeMdCell(text) {
    return String(text || '').replace(/\|/g, '\\|').replace(/\n/g, ' ');
}

function generate() {
    var sm = readJson(SM_JSON);
    var rules = ((sm && sm.params && sm.params.jobParams && sm.params.jobParams.rules) ||
                 (sm && sm.params && sm.params.rules) ||
                 []);

    var lines = [];
    lines.push('# dmtools-agents workflow (generated)');
    lines.push('');
    lines.push('Generated from `agents/sm.json`. Only enabled SM rules are shown.');
    lines.push('');

    // Rule table
    lines.push('## SM rules');
    lines.push('');
    lines.push('| # | Description | Types | Source statuses | Config file | Skip labels | Add label | Target status |');
    lines.push('|---:|---|---|---|---|---|---|---|');

    var usedStatuses = {};
    var usedAgents = {};
    var diagramEdges = [];

    rules.forEach(function(rule, idx) {
        if (rule.enabled === false) return;

        var sourceStatuses = parseSourceStatuses(rule.jql);
        var issueTypes = parseIssueTypes(rule.jql);
        var agent = agentNode(rule.configFile, idx);
        usedAgents[agent] = true;

        sourceStatuses.forEach(function(status) {
            usedStatuses[status] = true;
            diagramEdges.push('    ' + statusNode(status) + ' --> ' + agent);
        });

        if (rule.targetStatus) {
            usedStatuses[rule.targetStatus] = true;
            diagramEdges.push('    ' + agent + ' --> ' + statusNode(rule.targetStatus));
        }

        var skipLabels = '';
        if (rule.skipIfLabel) skipLabels = '`' + rule.skipIfLabel + '`';
        else if (rule.skipIfLabels && rule.skipIfLabels.length) {
            skipLabels = rule.skipIfLabels.map(function(l) { return '`' + l + '`'; }).join(', ');
        }

        lines.push([
            idx + 1,
            escapeMdCell(rule.description),
            issueTypes.join(', '),
            sourceStatuses.join(', '),
            '`' + rule.configFile + '`',
            skipLabels,
            rule.addLabel ? '`' + rule.addLabel + '`' : '',
            rule.targetStatus || '—'
        ].join(' | '));
    });

    lines.push('');

    // Mermaid flowchart
    lines.push('## Flow diagram');
    lines.push('');
    lines.push('```mermaid');
    lines.push('flowchart TD');

    Object.keys(usedStatuses).sort().forEach(function(status) {
        lines.push('    ' + statusNode(status));
    });

    diagramEdges.forEach(function(edge) {
        lines.push(edge);
    });

    lines.push('```');
    lines.push('');
    lines.push('---');
    lines.push('_Generated by js/agentWorkflowGraph.js_');

    fs.writeFileSync(WORKFLOW_MD, lines.join('\n'));
    console.log('✅ Generated', WORKFLOW_MD);
    return { success: true, rules: rules.length };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { generate };
}

if (require.main === module) {
    generate();
}

/**
 * DF Manager — deterministic Dark Factory watchdog.
 *
 * Audits Jira labels, GitHub PRs, and workflow runs for stuck automation states.
 * By default it is read-only and writes outputs/df_manager_report.json.
 * Set customParams.autoRecover=true to execute safe recovery actions.
 */

var configLoader = require('./configLoader.js');
var scmModule = require('./common/scm.js');
var trackersModule = require('./common/trackers.js');

var DEFAULT_SM_LABELS = [
    'sm_story_ba_check_triggered',
    'sm_story_acceptance_criteria_triggered',
    'sm_story_acceptance_criterias_triggered',
    'sm_story_solution_triggered',
    'sm_po_refinement_triggered',
    'sm_story_questions_triggered',
    'sm_task_intake_triggered',
    'sm_story_development_triggered',
    'sm_bug_development_triggered',
    'sm_bug_creation_triggered',
    'sm_story_review_triggered',
    'sm_pr_review_triggered',
    'sm_story_rework_triggered',
    'sm_pr_rework_triggered',
    'sm_pr_merge_triggered',
    'sm_test_cases_triggered',
    'sm_bug_merged_triggered',
    'sm_bug_test_cases_triggered',
    'sm_story_done_check_triggered',
    'sm_bug_done_check_triggered',
    'sm_task_done_check_triggered',
    'sm_test_automation_triggered',
    'sm_test_review_triggered',
    'sm_test_rework_triggered'
];

function parseJsonMaybe(value, fallback) {
    if (value === null || value === undefined || value === '') return fallback;
    if (typeof value !== 'string') return value;
    try { return JSON.parse(value); } catch (e) { return fallback; }
}

// Container keys used by tracker/SCM list responses (Jira paged values, ADO
// work items, GitHub workflow runs / composite results). Kept in priority order.
var ARRAY_CONTAINER_KEYS = ['values', 'items', 'workflow_runs', 'result'];

// Pure: return the first container key of `value` that holds an array, else null.
function firstArrayContainer(value) {
