        assert.equal(df.parseJsonMaybe(obj, 'fb'), obj);
        assert.equal(df.parseJsonMaybe(42, 'fb'), 42);
        assert.equal(df.parseJsonMaybe(['a'], 'fb'), obj === df.parseJsonMaybe(obj) ? obj : obj);
    });

    test('valid JSON string parses', function() {
